      WHEN OTHERS => 
        NULL;
    END CASE;
    s_stackNum_tmp <= sReg_stackNum;
    s_num_tmp <= sReg_num;
    s_cmd <= sReg_cmd;
    s_staticReads_tmp <= sReg_staticReads;
    s_epoch_tmp <= sReg_epoch;
    s_isConstant <= sReg_isConstant;
    count_next <= count_temp;
  END PROCESS MATLAB_Function_output;


  s_stackNum <= std_logic_vector(s_stackNum_tmp);

  s_num <= std_logic_vector(s_num_tmp);

  s_staticReads <= std_logic_vector(s_staticReads_tmp);

  s_epoch <= std_logic_vector(s_epoch_tmp);

END rtl;

